CREATE TYPE public.app_role AS ENUM ('professional','mentor','employer');
CREATE TABLE public.user_roles (user_id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL DEFAULT 'professional');
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_role ON public.user_roles FOR SELECT TO authenticated USING (user_id=auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, full_name text NOT NULL DEFAULT '', headline text NOT NULL DEFAULT '', location text NOT NULL DEFAULT '', summary text NOT NULL DEFAULT '', skills text[] NOT NULL DEFAULT '{}', education text NOT NULL DEFAULT '', experience text NOT NULL DEFAULT '', languages text[] NOT NULL DEFAULT '{}', certifications text NOT NULL DEFAULT '', portfolio_url text NOT NULL DEFAULT '', interests text[] NOT NULL DEFAULT '{}', visible_to_employers boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY read_profiles ON public.profiles FOR SELECT TO authenticated USING (id=auth.uid() OR (visible_to_employers AND (public.has_role(auth.uid(),'employer') OR public.has_role(auth.uid(),'mentor'))));
CREATE POLICY insert_profile ON public.profiles FOR INSERT TO authenticated WITH CHECK(id=auth.uid());
CREATE POLICY update_profile ON public.profiles FOR UPDATE TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE TABLE public.profile_documents (user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE, cv_path text NOT NULL);
GRANT SELECT,INSERT,UPDATE ON public.profile_documents TO authenticated; GRANT ALL ON public.profile_documents TO service_role;
ALTER TABLE public.profile_documents ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_docs ON public.profile_documents FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE POLICY employer_docs ON public.profile_documents FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'employer') AND EXISTS(SELECT 1 FROM public.profiles p WHERE p.id=user_id AND p.visible_to_employers));
CREATE TABLE public.mentors (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid UNIQUE REFERENCES public.profiles(id) ON DELETE CASCADE, name text NOT NULL, title text NOT NULL, company text NOT NULL DEFAULT '', industry text NOT NULL, skills text[] NOT NULL DEFAULT '{}', location text NOT NULL DEFAULT '', years_experience integer NOT NULL DEFAULT 5, bio text NOT NULL DEFAULT '', initials text NOT NULL DEFAULT '', available boolean NOT NULL DEFAULT true, is_demo boolean NOT NULL DEFAULT false);
GRANT SELECT ON public.mentors TO anon; GRANT SELECT,INSERT,UPDATE ON public.mentors TO authenticated; GRANT ALL ON public.mentors TO service_role;
ALTER TABLE public.mentors ENABLE ROW LEVEL SECURITY;
CREATE POLICY public_mentors ON public.mentors FOR SELECT USING(true);
CREATE POLICY manage_mentor ON public.mentors FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid() AND public.has_role(auth.uid(),'mentor'));
CREATE TABLE public.opportunities (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), employer_id uuid REFERENCES public.profiles(id) ON DELETE CASCADE, title text NOT NULL, company text NOT NULL, kind text NOT NULL CHECK(kind IN ('Job','Internship','Project','Volunteering','Challenge')), industry text NOT NULL DEFAULT 'Technology', skills text[] NOT NULL DEFAULT '{}', location text NOT NULL DEFAULT 'Remote', duration text NOT NULL DEFAULT '', description text NOT NULL, compensation text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','closed')), is_demo boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.opportunities TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.opportunities TO authenticated; GRANT ALL ON public.opportunities TO service_role;
ALTER TABLE public.opportunities ENABLE ROW LEVEL SECURITY;
CREATE POLICY read_open_opportunities ON public.opportunities FOR SELECT USING(status='open' OR employer_id=auth.uid());
CREATE POLICY manage_opportunities ON public.opportunities FOR ALL TO authenticated USING(employer_id=auth.uid()) WITH CHECK(employer_id=auth.uid() AND public.has_role(auth.uid(),'employer'));
CREATE TABLE public.applications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, opportunity_id uuid NOT NULL REFERENCES public.opportunities(id) ON DELETE CASCADE, cover_note text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'submitted' CHECK(status IN ('submitted','shortlisted','accepted','declined','completed')), feedback text NOT NULL DEFAULT '', reference text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,opportunity_id));
GRANT SELECT,INSERT,UPDATE ON public.applications TO authenticated; GRANT ALL ON public.applications TO service_role;
ALTER TABLE public.applications ENABLE ROW LEVEL SECURITY;
CREATE POLICY read_applications ON public.applications FOR SELECT TO authenticated USING(user_id=auth.uid() OR EXISTS(SELECT 1 FROM public.opportunities o WHERE o.id=opportunity_id AND o.employer_id=auth.uid()));
CREATE POLICY create_application ON public.applications FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND public.has_role(auth.uid(),'professional') AND EXISTS(SELECT 1 FROM public.opportunities o WHERE o.id=opportunity_id AND o.status='open'));
CREATE POLICY employer_update_application ON public.applications FOR UPDATE TO authenticated USING(EXISTS(SELECT 1 FROM public.opportunities o WHERE o.id=opportunity_id AND o.employer_id=auth.uid())) WITH CHECK(EXISTS(SELECT 1 FROM public.opportunities o WHERE o.id=opportunity_id AND o.employer_id=auth.uid()));
CREATE TABLE public.mentor_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, mentor_id uuid NOT NULL REFERENCES public.mentors(id) ON DELETE CASCADE, message text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','accepted','declined')), session_at timestamptz, feedback text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,mentor_id));
GRANT SELECT,INSERT,UPDATE ON public.mentor_requests TO authenticated; GRANT ALL ON public.mentor_requests TO service_role;
ALTER TABLE public.mentor_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY read_requests ON public.mentor_requests FOR SELECT TO authenticated USING(user_id=auth.uid() OR EXISTS(SELECT 1 FROM public.mentors m WHERE m.id=mentor_id AND m.user_id=auth.uid()));
CREATE POLICY create_request ON public.mentor_requests FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND public.has_role(auth.uid(),'professional'));
CREATE POLICY mentor_update_request ON public.mentor_requests FOR UPDATE TO authenticated USING(EXISTS(SELECT 1 FROM public.mentors m WHERE m.id=mentor_id AND m.user_id=auth.uid())) WITH CHECK(EXISTS(SELECT 1 FROM public.mentors m WHERE m.id=mentor_id AND m.user_id=auth.uid()));
CREATE TABLE public.messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), sender_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, recipient_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, body text NOT NULL CHECK(length(body)>0 AND length(body)<=5000), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.messages TO authenticated; GRANT ALL ON public.messages TO service_role;
ALTER TABLE public.messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY read_messages ON public.messages FOR SELECT TO authenticated USING(sender_id=auth.uid() OR recipient_id=auth.uid());
CREATE POLICY send_messages ON public.messages FOR INSERT TO authenticated WITH CHECK(sender_id=auth.uid() AND sender_id<>recipient_id AND EXISTS(SELECT 1 FROM public.profiles p WHERE p.id=recipient_id));
CREATE TABLE public.notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, title text NOT NULL, body text NOT NULL DEFAULT '', read boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,UPDATE ON public.notifications TO authenticated; GRANT ALL ON public.notifications TO service_role;
ALTER TABLE public.notifications ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_notifications ON public.notifications FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.demo_candidates (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), full_name text NOT NULL, headline text NOT NULL, location text NOT NULL, skills text[] NOT NULL, experience text NOT NULL, summary text NOT NULL);
GRANT SELECT ON public.demo_candidates TO authenticated; GRANT ALL ON public.demo_candidates TO service_role;
ALTER TABLE public.demo_candidates ENABLE ROW LEVEL SECURITY;
CREATE POLICY employer_demo_candidates ON public.demo_candidates FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'employer'));
CREATE FUNCTION public.handle_new_talentbridge_user() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.app_role; BEGIN r := CASE WHEN new.raw_user_meta_data->>'role'='mentor' THEN 'mentor'::public.app_role WHEN new.raw_user_meta_data->>'role'='employer' THEN 'employer'::public.app_role ELSE 'professional'::public.app_role END; INSERT INTO public.profiles(id,full_name) VALUES(new.id,coalesce(new.raw_user_meta_data->>'full_name',new.raw_user_meta_data->>'name','')); INSERT INTO public.user_roles(user_id,role) VALUES(new.id,r); INSERT INTO public.notifications(user_id,title,body) VALUES(new.id,'Welcome to TalentBridge','Your next chapter starts with your professional profile.'); IF r='mentor' THEN INSERT INTO public.mentors(user_id,name,title,industry) VALUES(new.id,coalesce(new.raw_user_meta_data->>'full_name','New mentor'),'Professional mentor','Technology'); END IF; RETURN new; END $$;
CREATE TRIGGER on_talentbridge_user_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.handle_new_talentbridge_user();
CREATE FUNCTION public.notify_talentbridge_activity() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE target uuid; BEGIN IF TG_TABLE_NAME='mentor_requests' THEN SELECT user_id INTO target FROM public.mentors WHERE id=new.mentor_id; IF TG_OP='UPDATE' THEN target:=new.user_id; END IF; ELSIF TG_TABLE_NAME='applications' THEN SELECT employer_id INTO target FROM public.opportunities WHERE id=new.opportunity_id; IF TG_OP='UPDATE' THEN target:=new.user_id; END IF; ELSE target:=new.recipient_id; END IF; IF target IS NOT NULL THEN INSERT INTO public.notifications(user_id,title,body) VALUES(target,CASE WHEN TG_TABLE_NAME='messages' THEN 'New message' WHEN TG_TABLE_NAME='mentor_requests' THEN 'Mentorship update' ELSE 'Application update' END,'Visit your workspace to see the latest update.'); END IF; RETURN new; END $$;
CREATE TRIGGER notify_mentor_requests AFTER INSERT OR UPDATE ON public.mentor_requests FOR EACH ROW EXECUTE FUNCTION public.notify_talentbridge_activity();
CREATE TRIGGER notify_applications AFTER INSERT OR UPDATE ON public.applications FOR EACH ROW EXECUTE FUNCTION public.notify_talentbridge_activity();
CREATE TRIGGER notify_messages AFTER INSERT ON public.messages FOR EACH ROW EXECUTE FUNCTION public.notify_talentbridge_activity();
