CREATE INDEX applications_opportunity_idx ON public.applications(opportunity_id);
CREATE INDEX mentor_requests_mentor_idx ON public.mentor_requests(mentor_id);
CREATE INDEX messages_recipient_idx ON public.messages(recipient_id);
CREATE INDEX notifications_user_idx ON public.notifications(user_id);